window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["miro"]={html:"<div class=\"own-miro\">\n  <div class=\"mi-promo\">\n    <span>Get your spot &mdash; Northwind live for the AI era</span>\n    <a href=\"#pricing\">Register free &rarr;</a>\n  </div>\n\n  <header class=\"mi-nav\">\n    <a class=\"mi-logo\" href=\"#\" aria-label=\"Northwind home\">\n      <span class=\"mi-wordmark\" aria-hidden=\"true\">N</span>\n      <span class=\"mi-logo-word\">Northwind</span>\n    </a>\n    <nav class=\"mi-nav-links\" aria-label=\"Primary\">\n      <a href=\"#product\">Product</a>\n      <a href=\"#solutions\">Solutions</a>\n      <a href=\"#resources\">Resources</a>\n      <a href=\"#pricing\">Pricing</a>\n    </nav>\n    <div class=\"mi-nav-right\">\n      <a class=\"mi-link\" href=\"#\">Log in</a>\n      <a class=\"mi-btn mi-btn-primary\" href=\"#pricing\">Get started free</a>\n      <button class=\"mi-menu\" type=\"button\" aria-label=\"Menu\" data-mi-menu>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 7h16M4 12h16M4 17h16\"/></svg>\n      </button>\n    </div>\n  </header>\n\n  <section class=\"mi-hero\" aria-labelledby=\"miHeroH\">\n    <h1 id=\"miHeroH\" class=\"mi-h1\">See how teams get great work done.</h1>\n    <p class=\"mi-hero-sub\">An AI-powered operations workspace &mdash; sticky notes, kanban, mind maps\n      and dashboards on one infinite board.</p>\n    <div class=\"mi-hero-cta\">\n      <a class=\"mi-btn mi-btn-primary mi-btn-lg\" href=\"#pricing\">Get started free</a>\n      <a class=\"mi-btn mi-btn-secondary mi-btn-lg\" href=\"#\">Book a demo</a>\n    </div>\n\n    <div class=\"mi-board\" aria-hidden=\"true\">\n      <div class=\"mi-board-top\"><span></span><span></span><span></span><i>north-loop board</i></div>\n      <div class=\"mi-board-canvas\">\n        <div class=\"mi-note mi-note-yellow\">Cut idle dock time</div>\n        <div class=\"mi-note mi-note-rose\">Nordics &mdash; 14%</div>\n        <div class=\"mi-note mi-note-coral\">APAC pilot Q3</div>\n        <div class=\"mi-note mi-note-teal\">Cycle 6.2 days</div>\n        <div class=\"mi-kanban\">\n          <div class=\"mi-col\"><span class=\"mi-chip\">To do</span><b></b><b></b></div>\n          <div class=\"mi-col\"><span class=\"mi-chip\">Doing</span><b></b></div>\n          <div class=\"mi-col\"><span class=\"mi-chip\">Done</span><b></b><b></b><b></b></div>\n        </div>\n        <svg class=\"mi-flow\" viewBox=\"0 0 600 300\" preserveAspectRatio=\"none\"><path d=\"M90 150 C 200 60, 320 240, 470 120\"/></svg>\n      </div>\n    </div>\n  </section>\n\n  <section id=\"product\" class=\"mi-sec\" aria-labelledby=\"miProdH\">\n    <div class=\"mi-sec-head\">\n      <h2 id=\"miProdH\" class=\"mi-h2\">Built for every kind of team.</h2>\n      <p class=\"mi-lead\">The colour you pin a note in is the colour of the workspace &mdash; the same\n        palette runs through every surface.</p>\n    </div>\n    <div class=\"mi-cards\">\n      <article class=\"mi-card mi-card-yellow\">\n        <span class=\"mi-card-tag mi-tag-yellow\">Yellow</span>\n        <h3 class=\"mi-h3\">Boards</h3>\n        <p class=\"mi-card-desc\">An infinite canvas for the messy middle of operations work.</p>\n      </article>\n      <article class=\"mi-card mi-card-rose\">\n        <span class=\"mi-card-tag mi-tag-rose\">Rose</span>\n        <h3 class=\"mi-h3\">AI workflows</h3>\n        <p class=\"mi-card-desc\">Turn a board into runs, automations and approvals.</p>\n      </article>\n      <article class=\"mi-card mi-card-coral\">\n        <span class=\"mi-card-tag mi-tag-coral\">Coral</span>\n        <h3 class=\"mi-h3\">Dashboards</h3>\n        <p class=\"mi-card-desc\">Pull live numbers next to the ideas that explain them.</p>\n      </article>\n      <article class=\"mi-card mi-card-teal\">\n        <span class=\"mi-card-tag mi-tag-teal\">Teal</span>\n        <h3 class=\"mi-h3\">Agile</h3>\n        <p class=\"mi-card-desc\">Plan the quarter and watch it move, together.</p>\n      </article>\n    </div>\n  </section>\n\n  <section id=\"solutions\" class=\"mi-sec mi-solutions\" aria-labelledby=\"miSolH\">\n    <div class=\"mi-split\">\n      <div class=\"mi-split-copy\">\n        <span class=\"mi-eyebrow\">AI at work</span>\n        <h2 id=\"miSolH\" class=\"mi-h2\">From sticky note to shipped.</h2>\n        <p class=\"mi-lead\">Northwind reads the board and helps you move it forward &mdash; summarise a\n          retro, draft the next sprint, or turn a cluster of notes into a plan.</p>\n        <ul class=\"mi-checks\">\n          <li>Summarise any board in one click</li>\n          <li>Turn notes into tasks and owners</li>\n          <li>Automate the handoffs you keep doing by hand</li>\n        </ul>\n        <a class=\"mi-btn mi-btn-secondary\" href=\"#\">Explore AI workflows</a>\n      </div>\n      <div class=\"mi-mockup\">\n        <div class=\"mi-mock-head\"><span></span><span></span><span></span></div>\n        <div class=\"mi-mock-body\">\n          <div class=\"mi-mock-row\"><span class=\"mi-mock-avatar\"></span><span class=\"mi-mock-line\"></span></div>\n          <div class=\"mi-mock-row\"><span class=\"mi-mock-avatar mi-a2\"></span><span class=\"mi-mock-line\"></span></div>\n          <div class=\"mi-mock-row\"><span class=\"mi-mock-avatar mi-a3\"></span><span class=\"mi-mock-line\"></span></div>\n          <div class=\"mi-mock-notes\">\n            <i class=\"mi-note-yellow\"></i><i class=\"mi-note-rose\"></i><i class=\"mi-note-teal\"></i><i class=\"mi-note-coral\"></i>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"mi-stats\" aria-labelledby=\"miStatsH\">\n    <h2 id=\"miStatsH\" class=\"mi-sr\">Northwind at scale</h2>\n    <div class=\"mi-stat-row\">\n      <div class=\"mi-stat\"><b>100M+</b><span>board users worldwide</span></div>\n      <div class=\"mi-stat\"><b>250k</b><span>companies onboard</span></div>\n      <div class=\"mi-stat\"><b>99.9%</b><span>board uptime</span></div>\n    </div>\n  </section>\n\n  <section id=\"pricing\" class=\"mi-sec\" aria-labelledby=\"miPriceH\">\n    <div class=\"mi-sec-head mi-center\">\n      <h2 id=\"miPriceH\" class=\"mi-h2\">Plans for every team.</h2>\n      <div class=\"mi-toggle\" role=\"group\" aria-label=\"Billing period\">\n        <span class=\"mi-toggle-thumb\" aria-hidden=\"true\"></span>\n        <button type=\"button\" class=\"mi-toggle-btn is-active\" data-mi-bill=\"mo\" aria-pressed=\"true\">Monthly</button>\n        <button type=\"button\" class=\"mi-toggle-btn\" data-mi-bill=\"yr\" aria-pressed=\"false\">Annual <span class=\"mi-badge-discount\">&minus;15%</span></button>\n      </div>\n    </div>\n    <div class=\"mi-tiers\">\n      <article class=\"mi-tier\">\n        <h3 class=\"mi-h3\">Free</h3>\n        <p class=\"mi-price\"><b data-mi-price data-mo=\"$0\" data-yr=\"$0\">$0</b><span>/mo</span></p>\n        <ul class=\"mi-tier-list\"><li>3 boards</li><li>Unlimited members</li><li>Core templates</li></ul>\n        <a class=\"mi-btn mi-btn-secondary mi-btn-block\" href=\"#\">Get started</a>\n      </article>\n      <article class=\"mi-tier\">\n        <h3 class=\"mi-h3\">Starter</h3>\n        <p class=\"mi-price\"><b data-mi-price data-mo=\"$12\" data-yr=\"$10\">$12</b><span>/mo</span></p>\n        <ul class=\"mi-tier-list\"><li>Unlimited boards</li><li>Private boards</li><li>Kanban &amp; tables</li></ul>\n        <a class=\"mi-btn mi-btn-secondary mi-btn-block\" href=\"#\">Choose Starter</a>\n      </article>\n      <article class=\"mi-tier mi-tier-featured\">\n        <span class=\"mi-tier-flag\">Most popular</span>\n        <h3 class=\"mi-h3\">Business</h3>\n        <p class=\"mi-price\"><b data-mi-price data-mo=\"$24\" data-yr=\"$20\">$24</b><span>/mo</span></p>\n        <ul class=\"mi-tier-list\"><li>AI workflows</li><li>Dashboards</li><li>Advanced permissions</li></ul>\n        <a class=\"mi-btn mi-btn-blue mi-btn-block\" href=\"#\">Choose Business</a>\n      </article>\n      <article class=\"mi-tier mi-tier-enterprise\">\n        <h3 class=\"mi-h3\">Enterprise</h3>\n        <p class=\"mi-price\">Custom</p>\n        <ul class=\"mi-tier-list\"><li>SSO &amp; SCIM</li><li>Governance</li><li>Dedicated success</li></ul>\n        <a class=\"mi-btn mi-btn-on-dark mi-btn-block\" href=\"#\">Contact sales</a>\n      </article>\n    </div>\n\n    <div class=\"mi-compare\">\n      <table class=\"mi-table\">\n        <caption class=\"mi-sr\">Feature comparison</caption>\n        <thead><tr><th scope=\"col\">Feature</th><th scope=\"col\">Free</th><th scope=\"col\">Starter</th><th scope=\"col\">Business</th><th scope=\"col\">Enterprise</th></tr></thead>\n        <tbody>\n          <tr class=\"mi-table-group\"><th scope=\"colgroup\" colspan=\"5\">Boards &amp; collaboration</th></tr>\n          <tr><td>Unlimited boards</td><td>&mdash;</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n          <tr><td>Private boards</td><td>&mdash;</td><td>&#10003;</td><td>&#10003;</td><td>&#10003;</td></tr>\n          <tr class=\"mi-table-group\"><th scope=\"colgroup\" colspan=\"5\">AI &amp; automation</th></tr>\n          <tr><td>AI workflows</td><td>&mdash;</td><td>&mdash;</td><td>&#10003;</td><td>&#10003;</td></tr>\n          <tr><td>Dashboards</td><td>&mdash;</td><td>&mdash;</td><td>&#10003;</td><td>&#10003;</td></tr>\n          <tr class=\"mi-table-group\"><th scope=\"colgroup\" colspan=\"5\">Security</th></tr>\n          <tr><td>Single sign-on</td><td>&mdash;</td><td>&mdash;</td><td>&mdash;</td><td>&#10003;</td></tr>\n        </tbody>\n      </table>\n    </div>\n  </section>\n\n  <section class=\"mi-cta\" aria-labelledby=\"miCtaH\">\n    <h2 id=\"miCtaH\" class=\"mi-h2\">Your team&rsquo;s next great board starts here.</h2>\n    <p class=\"mi-cta-sub\">Start free, invite the team, and see how much faster the work moves.</p>\n    <a class=\"mi-btn mi-btn-on-dark mi-btn-lg\" href=\"#pricing\">Get started free</a>\n  </section>\n\n  <footer class=\"mi-foot\">\n    <div class=\"mi-foot-top\">\n      <div class=\"mi-foot-brand\">\n        <span class=\"mi-wordmark mi-wordmark-light\" aria-hidden=\"true\">N</span>\n        <span class=\"mi-logo-word\">Northwind</span>\n      </div>\n      <div class=\"mi-foot-grid\">\n        <div class=\"mi-foot-col\"><h3>Product</h3><a href=\"#\">Boards</a><a href=\"#\">AI workflows</a><a href=\"#\">Dashboards</a></div>\n        <div class=\"mi-foot-col\"><h3>Solutions</h3><a href=\"#\">Operations</a><a href=\"#\">Product</a><a href=\"#\">Agile</a></div>\n        <div class=\"mi-foot-col\"><h3>Tools</h3><a href=\"#\">Templates</a><a href=\"#\">Tutorials</a><a href=\"#\">Integrations</a></div>\n        <div class=\"mi-foot-col\"><h3>Resources</h3><a href=\"#\">Blog</a><a href=\"#\">Help centre</a><a href=\"#\">Community</a></div>\n        <div class=\"mi-foot-col\"><h3>Company</h3><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">News</a></div>\n        <div class=\"mi-foot-col\"><h3>Plans &amp; pricing</h3><a href=\"#\">Free</a><a href=\"#\">Business</a><a href=\"#\">Enterprise</a></div>\n      </div>\n    </div>\n    <div class=\"mi-foot-bottom\">\n      <span>&copy; 2026 Northwind Analytics</span>\n      <div class=\"mi-store\">\n        <a class=\"mi-store-badge\" href=\"#\">App Store</a>\n        <a class=\"mi-store-badge\" href=\"#\">Google Play</a>\n      </div>\n      <span class=\"mi-foot-links\"><a href=\"#\">Privacy</a><a href=\"#\">Terms</a><a href=\"#\">Cookies</a></span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — own layout in the Miro design language ═════════════════════\n   White canvas with a canary-yellow wordmark, Roobert PRO at 80px with -2px\n   tracking, black-pill CTAs, pastel feature cards (yellow/rose/coral/teal) echoing\n   the sticky-note palette, real board mockups, a 4-tier pricing grid and a dense\n   dark footer. */\n\n.own-miro {\n  --primary: #1c1c1e;\n  --charcoal: #2c2c34;\n  --canvas: #ffffff;\n  --surface: #f7f8fa;\n  --surface-soft: #fafbfc;\n  --surface-yellow: #fff8e0;\n  --surface-featured: #f5f3ff;\n  --hairline: #e0e2e8;\n  --hairline-soft: #eef0f3;\n  --hairline-strong: #c7cad5;\n  --ink-deep: #050038;\n  --ink: #1c1c1e;\n  --slate: #555a6a;\n  --steel: #6b6f7e;\n  --stone: #8e91a0;\n  --muted: #a5a8b5;\n  --yellow: #ffd02f;\n  --yellow-light: #fff4c4;\n  --yellow-dark: #746019;\n  --blue: #4262ff;\n  --blue-pressed: #2a41b6;\n  --coral-light: #ffc6c6;\n  --coral-dark: #600000;\n  --rose-light: #fde0f0;\n  --teal-light: #c3faf5;\n  --moss-dark: #187574;\n  --success: #00b473;\n  --footer-bg: #1c1c1e;\n  --font: 'Roobert PRO', 'Noto Sans', -apple-system, BlinkMacSystemFont, sans-serif;\n  --gut: clamp(20px, 5cqi, 48px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--font);\n  font-size: 16px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n}\n.own-miro *,\n.own-miro *::before,\n.own-miro *::after { box-sizing: border-box; }\n.own-miro :focus-visible { outline: 2px solid var(--blue); outline-offset: 2px; border-radius: 6px; }\n.own-miro .mi-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n\n/* ── type ────────────────────────────────────────────────────────────────── */\n.own-miro .mi-h1 { font-weight: 500; font-size: clamp(38px, 6cqi, 80px); line-height: 1.05; letter-spacing: -2px; }\n.own-miro .mi-h2 { font-weight: 500; font-size: clamp(28px, 3.6cqi, 48px); line-height: 1.15; letter-spacing: -1px; }\n.own-miro .mi-h3 { font-weight: 500; font-size: 22px; line-height: 1.3; }\n.own-miro .mi-lead { color: var(--slate); font-size: 18px; line-height: 1.5; max-width: 60ch; margin-top: 14px; }\n.own-miro .mi-eyebrow { display: inline-block; font-size: 12px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--steel); margin-bottom: 14px; }\n\n/* ── buttons ────────────────────────────────────────────────────────────── */\n.own-miro .mi-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 44px; padding: 0 24px; border: 1px solid transparent; border-radius: 9999px; cursor: pointer;\n  font-family: var(--font); font-size: 14px; font-weight: 500; line-height: 1.3;\n  text-decoration: none; transition: background-color .15s, border-color .15s;\n}\n.own-miro .mi-btn-lg { height: 52px; padding: 0 30px; font-size: 15px; }\n.own-miro .mi-btn-primary { background: var(--primary); color: #fff; }\n.own-miro .mi-btn-primary:active { background: var(--charcoal); }\n.own-miro .mi-btn-secondary { background: transparent; color: var(--ink); border-color: var(--hairline-strong); }\n.own-miro .mi-btn-secondary:hover { border-color: var(--ink); }\n.own-miro .mi-btn-blue { background: var(--blue); color: #fff; }\n.own-miro .mi-btn-on-dark { background: #fff; color: var(--primary); }\n.own-miro .mi-btn-block { width: 100%; }\n\n/* ── promo + nav ─────────────────────────────────────────────────────────── */\n.own-miro .mi-promo { display: flex; align-items: center; justify-content: center; gap: 14px; flex-wrap: wrap; background: var(--primary); color: #fff; padding: 10px 24px; font-size: 14px; font-weight: 500; }\n.own-miro .mi-promo a { color: var(--yellow); text-decoration: none; font-weight: 600; }\n.own-miro .mi-nav { position: sticky; top: 68px; z-index: 30; display: flex; align-items: center; gap: 26px; padding: 12px var(--gut); background: rgba(255,255,255,.92); backdrop-filter: blur(10px); border-bottom: 1px solid var(--hairline-soft); }\n.own-miro .mi-logo { display: inline-flex; align-items: center; gap: 10px; text-decoration: none; color: var(--ink); }\n.own-miro .mi-wordmark { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 8px; background: var(--yellow); color: var(--primary); font-size: 16px; font-weight: 600; }\n.own-miro .mi-wordmark-light { background: var(--yellow); }\n.own-miro .mi-logo-word { font-weight: 500; font-size: 18px; letter-spacing: -.4px; }\n.own-miro .mi-nav-links { display: flex; align-items: center; gap: 24px; margin-left: 8px; }\n.own-miro .mi-nav-links a { color: var(--ink); text-decoration: none; font-size: 14px; font-weight: 500; }\n.own-miro .mi-nav-links a:hover { color: var(--blue); }\n.own-miro .mi-nav-right { margin-left: auto; display: flex; align-items: center; gap: 12px; }\n.own-miro .mi-link { color: var(--ink); text-decoration: none; font-size: 14px; font-weight: 500; }\n.own-miro .mi-link:hover { color: var(--blue); }\n.own-miro .mi-menu { display: none; width: 44px; height: 44px; align-items: center; justify-content: center; border: 1px solid var(--hairline); border-radius: 9999px; background: var(--canvas); cursor: pointer; }\n.own-miro .mi-menu svg { width: 18px; height: 18px; fill: none; stroke: var(--ink); stroke-width: 2; stroke-linecap: round; }\n\n/* ── hero ────────────────────────────────────────────────────────────────── */\n.own-miro .mi-hero { padding: clamp(56px, 8cqi, 120px) var(--gut) clamp(40px, 5cqi, 64px); text-align: center; }\n.own-miro .mi-hero .mi-h1 { max-width: 18ch; margin: 0 auto; }\n.own-miro .mi-hero-sub { color: var(--slate); font-size: 18px; line-height: 1.5; max-width: 52ch; margin: 20px auto 0; }\n.own-miro .mi-hero-cta { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-top: 30px; }\n.own-miro .mi-board { position: relative; max-width: 940px; margin: clamp(36px, 5cqi, 64px) auto 0; background: var(--canvas); border: 1px solid var(--hairline-soft); border-radius: 16px; overflow: hidden; box-shadow: rgba(5,0,56,.08) 0px 12px 32px -4px; }\n.own-miro .mi-board-top { display: flex; align-items: center; gap: 7px; padding: 12px 16px; border-bottom: 1px solid var(--hairline-soft); }\n.own-miro .mi-board-top span { width: 11px; height: 11px; border-radius: 50%; background: var(--hairline); }\n.own-miro .mi-board-top i { margin-left: 12px; font-style: normal; font-size: 12px; color: var(--stone); }\n.own-miro .mi-board-canvas { position: relative; min-height: 340px; background-image: radial-gradient(var(--hairline) 1px, transparent 1px); background-size: 22px 22px; padding: 34px; }\n.own-miro .mi-note { position: absolute; width: 150px; padding: 14px 16px; font-size: 14px; font-weight: 500; line-height: 1.35; border-radius: 4px; box-shadow: rgba(5,0,56,.12) 0px 6px 16px -6px; }\n.own-miro .mi-note-yellow { background: var(--yellow-light); left: 6%; top: 18%; transform: rotate(-3deg); }\n.own-miro .mi-note-rose { background: var(--rose-light); left: 30%; top: 8%; transform: rotate(2deg); }\n.own-miro .mi-note-coral { background: var(--coral-light); left: 4%; top: 56%; transform: rotate(2deg); }\n.own-miro .mi-note-teal { background: var(--teal-light); left: 28%; top: 62%; transform: rotate(-2deg); }\n.own-miro .mi-kanban { position: absolute; right: 4%; top: 20%; display: flex; gap: 12px; }\n.own-miro .mi-col { width: 108px; background: var(--surface); border-radius: 10px; padding: 12px; display: grid; gap: 8px; align-content: start; }\n.own-miro .mi-chip { font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--steel); }\n.own-miro .mi-col b { display: block; height: 30px; border-radius: 6px; background: var(--canvas); box-shadow: 0 1px 0 var(--hairline); }\n.own-miro .mi-flow { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; }\n.own-miro .mi-flow path { fill: none; stroke: var(--blue); stroke-width: 1.5; stroke-dasharray: 2 7; stroke-linecap: round; opacity: .5; }\n\n/* ── sections ───────────────────────────────────────────────────────────── */\n.own-miro .mi-sec { padding: clamp(48px, 6cqi, 96px) var(--gut); max-width: 1280px; margin: 0 auto; }\n.own-miro .mi-sec-head { max-width: 680px; margin-bottom: 40px; }\n.own-miro .mi-sec-head.mi-center { margin-left: auto; margin-right: auto; text-align: center; }\n.own-miro .mi-cards { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; }\n.own-miro .mi-card { position: relative; border-radius: 28px; padding: 32px; min-height: 220px; display: flex; flex-direction: column; }\n.own-miro .mi-card-yellow { background: var(--yellow); color: var(--primary); }\n.own-miro .mi-card-rose { background: var(--rose-light); color: var(--primary); }\n.own-miro .mi-card-coral { background: var(--coral-light); color: var(--primary); }\n.own-miro .mi-card-teal { background: var(--teal-light); color: var(--primary); }\n.own-miro .mi-card-tag { position: absolute; top: 24px; right: 24px; padding: 4px 10px; border-radius: 9999px; font-size: 12px; font-weight: 600; }\n.own-miro .mi-tag-yellow { background: var(--surface-yellow); color: var(--yellow-dark); }\n.own-miro .mi-tag-rose { background: #fff; color: var(--coral-dark); }\n.own-miro .mi-tag-coral { background: #fff; color: var(--coral-dark); }\n.own-miro .mi-tag-teal { background: #fff; color: var(--moss-dark); }\n.own-miro .mi-card .mi-h3 { margin-top: auto; }\n.own-miro .mi-card-desc { margin-top: 8px; font-size: 14px; line-height: 1.5; opacity: .85; }\n\n/* split */\n.own-miro .mi-split { display: grid; grid-template-columns: 1fr 1.1fr; gap: clamp(28px, 4cqi, 64px); align-items: center; }\n.own-miro .mi-checks { list-style: none; margin: 24px 0; padding: 0; display: grid; gap: 12px; }\n.own-miro .mi-checks li { position: relative; padding-left: 30px; font-size: 15px; color: var(--slate); }\n.own-miro .mi-checks li::before { content: ''; position: absolute; left: 0; top: 3px; width: 16px; height: 9px; border-left: 2px solid var(--success); border-bottom: 2px solid var(--success); transform: rotate(-45deg); }\n.own-miro .mi-mockup { background: var(--canvas); border: 1px solid var(--hairline-soft); border-radius: 16px; overflow: hidden; box-shadow: rgba(5,0,56,.08) 0px 12px 32px -4px; }\n.own-miro .mi-mock-head { display: flex; gap: 7px; padding: 12px 16px; border-bottom: 1px solid var(--hairline-soft); }\n.own-miro .mi-mock-head span { width: 11px; height: 11px; border-radius: 50%; background: var(--hairline); }\n.own-miro .mi-mock-body { padding: 22px; display: grid; gap: 16px; }\n.own-miro .mi-mock-row { display: flex; align-items: center; gap: 12px; }\n.own-miro .mi-mock-avatar { width: 34px; height: 34px; border-radius: 50%; background: var(--yellow); flex: none; }\n.own-miro .mi-mock-avatar.mi-a2 { background: var(--coral-light); }\n.own-miro .mi-mock-avatar.mi-a3 { background: var(--teal-light); }\n.own-miro .mi-mock-line { height: 12px; border-radius: 6px; background: var(--surface); flex: 1; }\n.own-miro .mi-mock-notes { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; }\n.own-miro .mi-mock-notes i { display: block; height: 84px; border-radius: 6px; }\n.own-miro .mi-mock-notes .mi-note-yellow { background: var(--yellow-light); }\n.own-miro .mi-mock-notes .mi-note-rose { background: var(--rose-light); }\n.own-miro .mi-mock-notes .mi-note-teal { background: var(--teal-light); }\n.own-miro .mi-mock-notes .mi-note-coral { background: var(--coral-light); }\n\n/* stats */\n.own-miro .mi-stats { padding: clamp(40px, 5cqi, 72px) var(--gut); background: var(--surface); }\n.own-miro .mi-stat-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; max-width: 1000px; margin: 0 auto; text-align: center; }\n.own-miro .mi-stat b { display: block; font-weight: 500; font-size: clamp(40px, 5cqi, 64px); line-height: 1.1; letter-spacing: -1.5px; }\n.own-miro .mi-stat span { display: block; margin-top: 8px; font-size: 14px; color: var(--steel); }\n\n/* ── pricing ─────────────────────────────────────────────────────────────── */\n.own-miro .mi-toggle { position: relative; display: inline-flex; gap: 4px; padding: 4px; border-radius: 9999px; background: var(--surface); margin-top: 20px; }\n.own-miro .mi-toggle-btn { position: relative; z-index: 1; display: inline-flex; align-items: center; gap: 6px; height: 36px; padding: 0 16px; border: 0; border-radius: 9999px; background: transparent; color: var(--steel); font-family: var(--font); font-size: 14px; font-weight: 500; cursor: pointer; }\n.own-miro .mi-toggle-btn.is-active { background: var(--canvas); color: var(--ink); box-shadow: rgba(5,0,56,.06) 0px 1px 2px 0px; }\n.own-miro .mi-badge-discount { display: inline-flex; padding: 2px 6px; border-radius: 6px; background: var(--yellow); color: var(--primary); font-size: 12px; font-weight: 600; }\n.own-miro .mi-tiers { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-top: 36px; }\n.own-miro .mi-tier { position: relative; background: var(--canvas); border: 1px solid var(--hairline); border-radius: 16px; padding: 32px; display: flex; flex-direction: column; }\n.own-miro .mi-tier-featured { background: var(--surface-featured); border: 2px solid var(--blue); }\n.own-miro .mi-tier-enterprise { background: var(--primary); color: #fff; border-color: var(--primary); }\n.own-miro .mi-tier-flag { position: absolute; top: -12px; left: 32px; padding: 3px 10px; border-radius: 9999px; background: var(--blue); color: #fff; font-size: 12px; font-weight: 600; }\n.own-miro .mi-price { font-weight: 500; font-size: clamp(32px, 3.6cqi, 44px); letter-spacing: -1.5px; margin: 12px 0 20px; }\n.own-miro .mi-price b { font-weight: 500; }\n.own-miro .mi-price span { font-size: 14px; font-weight: 400; color: var(--steel); }\n.own-miro .mi-tier-enterprise .mi-price span { color: var(--muted); }\n.own-miro .mi-tier-list { list-style: none; margin: 0 0 24px; padding: 0; display: grid; gap: 12px; flex: 1; }\n.own-miro .mi-tier-list li { position: relative; padding-left: 28px; font-size: 14px; }\n.own-miro .mi-tier-list li::before { content: ''; position: absolute; left: 0; top: 4px; width: 15px; height: 8px; border-left: 2px solid var(--success); border-bottom: 2px solid var(--success); transform: rotate(-45deg); }\n.own-miro .mi-compare { margin-top: 48px; overflow-x: auto; }\n.own-miro .mi-table { width: 100%; border-collapse: collapse; border: 1px solid var(--hairline); border-radius: 8px; overflow: hidden; min-width: 640px; }\n.own-miro .mi-table th, .own-miro .mi-table td { text-align: left; padding: 14px 18px; font-size: 14px; }\n.own-miro .mi-table thead th { background: var(--surface); font-size: 13px; font-weight: 600; color: var(--steel); }\n.own-miro .mi-table tbody tr { border-top: 1px solid var(--hairline-soft); }\n.own-miro .mi-table-group th { padding: 12px 18px; background: var(--surface-soft); font-size: 11px; font-weight: 600; letter-spacing: .5px; text-transform: uppercase; color: var(--steel); }\n\n/* ── cta ──────────────────────────────────────────────────────────────────── */\n.own-miro .mi-cta { margin: 0 var(--gut) clamp(48px, 6cqi, 96px); background: var(--primary); color: #fff; border-radius: 32px; padding: clamp(48px, 7cqi, 96px) 32px; text-align: center; display: grid; gap: 18px; justify-items: center; }\n.own-miro .mi-cta .mi-h2 { color: #fff; max-width: 22ch; }\n.own-miro .mi-cta-sub { color: var(--muted); font-size: 16px; max-width: 48ch; }\n\n/* ── footer ──────────────────────────────────────────────────────────────── */\n.own-miro .mi-foot { background: var(--footer-bg); color: #fff; padding: clamp(44px, 6cqi, 72px) var(--gut) 32px; }\n.own-miro .mi-foot-top { display: grid; grid-template-columns: 200px 1fr; gap: 40px; max-width: 1280px; margin: 0 auto; }\n.own-miro .mi-foot-brand { display: flex; align-items: center; gap: 10px; }\n.own-miro .mi-foot-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 24px; }\n.own-miro .mi-foot-col h3 { font-size: 14px; font-weight: 500; margin-bottom: 14px; }\n.own-miro .mi-foot-col a { display: block; color: var(--muted); text-decoration: none; font-size: 14px; margin-bottom: 10px; }\n.own-miro .mi-foot-col a:hover { color: #fff; }\n.own-miro .mi-foot-bottom { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; max-width: 1280px; margin: 44px auto 0; padding-top: 20px; border-top: 1px solid rgba(255,255,255,.14); font-size: 13px; color: var(--muted); }\n.own-miro .mi-store { display: flex; gap: 10px; }\n.own-miro .mi-store-badge { padding: 8px 14px; border-radius: 8px; background: #fff; color: var(--primary); font-size: 13px; font-weight: 600; text-decoration: none; }\n.own-miro .mi-foot-links { display: flex; gap: 20px; }\n.own-miro .mi-foot-links a { color: var(--muted); text-decoration: none; }\n.own-miro .mi-foot-links a:hover { color: #fff; }\n\n/* ── responsive ──────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-miro .mi-nav-links { display: none; }\n  .own-miro .mi-cards { grid-template-columns: repeat(2, 1fr); }\n  .own-miro .mi-split { grid-template-columns: 1fr; }\n  .own-miro .mi-tiers { grid-template-columns: repeat(2, 1fr); }\n  .own-miro .mi-foot-top { grid-template-columns: 1fr; gap: 28px; }\n  .own-miro .mi-foot-grid { grid-template-columns: repeat(3, 1fr); }\n}\n@container frame (max-width: 760px) {\n  .own-miro .mi-nav { top: 10px; gap: 12px; padding: 10px 14px; }\n  .own-miro .mi-nav-right .mi-link, .own-miro .mi-nav-right .mi-btn { display: none; }\n  .own-miro .mi-menu { display: inline-flex; margin-left: auto; }\n  .own-miro .mi-kanban { display: none; }\n  .own-miro .mi-note { width: 128px; }\n  .own-miro .mi-stat-row { grid-template-columns: 1fr; gap: 24px; }\n  .own-miro .mi-tiers { grid-template-columns: 1fr; }\n  .own-miro .mi-foot-grid { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 430px) {\n  .own-miro .mi-cards, .own-miro .mi-foot-grid { grid-template-columns: 1fr; }\n  .own-miro .mi-board-canvas { min-height: 420px; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-miro *, .own-miro *::before, .own-miro *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — Miro own-layout behaviour ═════════════════════════════════
   Registers window.OWN_LAYOUTS['miro'].init(root). Keeps the pricing toggle and
   the mobile menu interactive. Returns a cleanup removing every listener. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['miro'] = {
    init: function (root) {
      var billBtns = Array.prototype.slice.call(root.querySelectorAll('[data-mi-bill]'));
      var prices = Array.prototype.slice.call(root.querySelectorAll('[data-mi-price]'));
      var menu = root.querySelector('[data-mi-menu]');
      var links = root.querySelector('.mi-nav-links');

      function onBill(e) {
        var mode = e.currentTarget.getAttribute('data-mi-bill');
        billBtns.forEach(function (b) {
          var on = b === e.currentTarget;
          b.classList.toggle('is-active', on);
          b.setAttribute('aria-pressed', on ? 'true' : 'false');
        });
        prices.forEach(function (p) {
          var v = p.getAttribute('data-' + mode);
          if (v) p.textContent = v;
        });
      }
      function onMenu() {
        if (!links) return;
        var open = links.getAttribute('data-open') === '1';
        links.setAttribute('data-open', open ? '0' : '1');
        links.style.display = open ? '' : 'grid';
        links.style.position = 'absolute';
        links.style.top = '64px';
        links.style.left = '12px';
        links.style.right = '12px';
        links.style.margin = '0';
        links.style.padding = '14px';
        links.style.gap = '4px';
        links.style.background = '#fff';
        links.style.border = '1px solid var(--hairline)';
        links.style.borderRadius = '14px';
        links.style.boxShadow = 'rgba(5,0,56,.12) 0px 12px 32px -8px';
        links.style.zIndex = '40';
      }

      billBtns.forEach(function (b) { b.addEventListener('click', onBill); });
      if (menu) menu.addEventListener('click', onMenu);

      return function cleanup() {
        billBtns.forEach(function (b) { b.removeEventListener('click', onBill); });
        if (menu) menu.removeEventListener('click', onMenu);
        if (links) { links.removeAttribute('style'); links.removeAttribute('data-open'); }
      };
    }
  };
})();
